const trigger = $input.first().json;
// Soporta dos modos: parámetro directo 'books' (string) o parámetro 'input' (JSON string con {books:[...]})
let books;
if (trigger.books !== undefined) {
  const raw = trigger.books;
  if (Array.isArray(raw)) {
    books = raw;
  } else {
    try { books = JSON.parse(String(raw)); } catch { books = []; }
  }
} else if (trigger.input !== undefined) {
  const raw = trigger.input;
  const inp = typeof raw === 'string' ? JSON.parse(raw) : (raw || trigger);
  books = inp.books;
  if (!Array.isArray(books)) {
    try { books = JSON.parse(String(books)); } catch { books = []; }
  }
} else {
  books = [];
}

if (!Array.isArray(books) || books.length === 0) throw new Error('books debe ser un array no vacío');
books = books.slice(0, 5);
const validated = [];
const skipped = [];
for (const b of books) {
  const title = typeof b.title === 'string' ? b.title.trim() : '';
  const author = typeof b.author === 'string' ? b.author.trim() : '';
  const isbn = typeof b.isbn === 'string' ? b.isbn.trim().replace(/[^0-9X]/gi, '') : '';
  const description = typeof b.description === 'string' ? b.description.slice(0, 2000) : null;
  const coverUrl = typeof b.coverUrl === 'string' ? b.coverUrl.trim() : '';
  const categoryNames = Array.isArray(b.categoryNames) ? b.categoryNames.filter(c => typeof c === 'string' && c.trim()).map(c => c.trim()) : [];
  if (!title) { skipped.push({ title: b.title || '?', reason: 'título vacío' }); continue; }
  if (!author) { skipped.push({ title, reason: 'autor vacío' }); continue; }
  if (isbn.length !== 10 && isbn.length !== 13) { skipped.push({ title, reason: `ISBN inválido: ${isbn}` }); continue; }
  if (!coverUrl.startsWith('https://')) { skipped.push({ title, reason: 'coverUrl no HTTPS' }); continue; }
  validated.push({ title, author, isbn, description, coverUrl, categoryNames });
}
return [{ json: { validated, skipped } }];

// Skip HEAD validation — fetch() is not available in Code node sandbox.
// Books from search_external_books already have coverAvailable:true.
// Only require HTTPS (already validated in Validar Input).
const data = $input.first().json;
const { validated, skipped } = data;

const ready = validated.filter(b => b.coverUrl && b.coverUrl.startsWith('https://'));
const newSkipped = [...skipped];

for (const b of validated) {
  if (!b.coverUrl || !b.coverUrl.startsWith('https://')) {
    newSkipped.push({ title: b.title, reason: 'coverUrl no HTTPS' });
  }
}

return [{ json: { ready, skipped: newSkipped } }];

const coverData = $('Validar Portadas').first().json;
const isbnRow = $input.first().json;
const existingIsbnArr = Array.isArray(isbnRow.existing_isbns) ? isbnRow.existing_isbns : [];
const existingIsbns = new Set(existingIsbnArr.filter(Boolean).map(String));

const toInsert = [];
const skipped = [...coverData.skipped];

for (const b of coverData.ready) {
  if (existingIsbns.has(b.isbn)) {
    skipped.push({ title: b.title, reason: `ISBN ${b.isbn} ya existe en catálogo` });
  } else {
    toInsert.push(b);
  }
}

return [{ json: { toInsert, skipped } }];

// Inserta los libros válidos en catalog_books en transacción
const filterData = $('Filtrar Existentes').first().json;
const catRows = $input.all();

const categoryMap = {};
for (const r of catRows) {
  if (r.json?.id && r.json?.name) {
    categoryMap[r.json.name.toLowerCase()] = Number(r.json.id);
  }
}

const { toInsert, skipped } = filterData;

if (toInsert.length === 0) {
  return [{ json: { insertedBooks: [], skipped } }];
}

// Construir sentencias INSERT para ejecutar por lotes
// Devolvemos la info para que el siguiente nodo Postgres la ejecute
const statements = [];

for (const b of toInsert) {
  const t = b.title.replace(/'/g, "''");
  const a = b.author.replace(/'/g, "''");
  const isbn = b.isbn.replace(/'/g, "''");
  const desc = b.description ? b.description.replace(/'/g, "''") : null;
  const cover = b.coverUrl.replace(/'/g, "''");

  const descSql = desc ? `'${desc}'` : 'NULL';
  statements.push(`INSERT INTO catalog_books (title, author, isbn, description, cover_url, price, stock, created_at, updated_at)
VALUES ('${t}', '${a}', '${isbn}', ${descSql}, '${cover}', 9.99, 5, NOW(), NOW())
RETURNING id, title`);

  // Resolución de categorías: usar las que matcheen, sino 'Novedades'
  const matchedCategoryIds = b.categoryNames
    .map(name => categoryMap[name.toLowerCase()])
    .filter(Boolean);
  if (matchedCategoryIds.length === 0) {
    const defaultId = categoryMap['novedades'];
    if (defaultId) matchedCategoryIds.push(defaultId);
  }
  b._resolvedCategoryIds = matchedCategoryIds;
}

return [{ json: { statements, toInsert, skipped, categoryMap } }];

// Ejecuta los INSERTs libro a libro y registra los IDs
// Usamos la credencial de Postgres directamente via $helpers.request no disponible.
// En su lugar, generamos un único SQL multi-insert concatenado.

const data = $input.first().json;
const { toInsert, skipped } = data;

if (toInsert.length === 0) {
  return [{ json: { insertedBooks: [], skipped } }];
}

// Construir VALUES multi-row para mayor eficiencia
const valueRows = toInsert.map(b => {
  const t = b.title.replace(/'/g, "''");
  const a = b.author.replace(/'/g, "''");
  const isbn = b.isbn.replace(/'/g, "''");
  const desc = b.description ? `'${b.description.replace(/'/g, "''")}'` : 'NULL';
  const cover = b.coverUrl.replace(/'/g, "''");
  return `('${t}', '${a}', '${isbn}', ${desc}, '${cover}', 9.99, 5, NOW(), NOW())`;
}).join(',\n');

const sql = `INSERT INTO catalog_books (title, author, isbn, description, cover_url, price, stock, created_at, updated_at)\nVALUES\n${valueRows}\nRETURNING id, title, isbn`;

return [{ json: { sql, toInsert, skipped } }];

// Inserta las relaciones libro-categoría usando los IDs recién creados
const insertedRows = $input.all();
const buildData = $('Construir SQL').first().json;
const { toInsert, skipped } = buildData;

const insertedBooks = [];
const newSkipped = [...skipped];

// Mapear isbn → id recién insertado
const isbnToId = {};
for (const r of insertedRows) {
  const j = r.json;
  if (j?.error) {
    // Fallo general: todos los libros del batch se marcan como fallidos
    newSkipped.push(...toInsert.map(b => ({ title: b.title, reason: j.error.message || 'INSERT falló' })));
    break;
  }
  if (j?.id && j?.isbn) {
    isbnToId[j.isbn] = Number(j.id);
    insertedBooks.push({ id: Number(j.id), title: j.title || '' });
  }
}

// Preparar sql de categorías
const catValueRows = [];
for (const b of toInsert) {
  const bookId = isbnToId[b.isbn];
  if (!bookId) continue;
  for (const catId of (b._resolvedCategoryIds || [])) {
    catValueRows.push(`(${bookId}, ${catId})`);
  }
}

const catSql = catValueRows.length > 0
  ? `INSERT INTO catalog_book_categories (catalog_book_id, category_id) VALUES ${catValueRows.join(', ')} ON CONFLICT DO NOTHING`
  : null;

return [{ json: { insertedBooks, skipped: newSkipped, catSql } }];

// Rama sin categorías: pasar directo al resultado final
const d = $input.first().json;
return [{ json: { insertedBooks: d.insertedBooks, skipped: d.skipped } }];

// Resultado final tras insertar categorías
const procData = $('Procesar Insertados').first().json;
return [{ json: { insertedBooks: procData.insertedBooks, skipped: procData.skipped } }];
